function viennaNow(){const f=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Vienna',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});const v=Object.fromEntries(f.formatToParts().map(x=>[x.type,x.value]));return {date:v.year+'-'+v.month+'-'+v.day,time:v.hour+':'+v.minute};}
function dateBounds(){const n=viennaNow();const last=new Date(n.date+'T12:00:00Z');last.setUTCDate(last.getUTCDate()+90);return [n.date,last.toISOString().slice(0,10)];}
function setDateBounds(){const d=$('date'),t=$('time');if(!d||!t)return;const [min,max]=dateBounds();d.min=min;d.max=max;const n=viennaNow();t.min=d.value===n.date?n.time:'';}

function loadTurnstile(){
 if(window.turnstile)return Promise.resolve(window.turnstile);
 if(!widgetPromise)widgetPromise=new Promise((resolve,reject)=>{
  const script=document.createElement('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit';script.async=true;
  script.onload=()=>window.turnstile?resolve(window.turnstile):reject(new Error('Turnstile unavailable'));
  script.onerror=()=>{script.remove();reject(new Error('Turnstile unavailable'))};document.head.append(script);
 }).catch(e=>{widgetPromise=null;throw e});
 return widgetPromise;
}
