async function setupBooking(form){
 const button=form.querySelector('button[type=submit]');button.disabled=true;tfCalendar(form);
 if(!configured||location.protocol==='file:'){msg(tr('Vorschau: Online-Anfragen sind noch nicht aktiviert.','Preview: online booking is not enabled yet.','Попередній перегляд: онлайн-запис ще не активовано.'));return;}
 let token='',busy=false;
 try{const ts=await loadTurnstile();if(!form.isConnected)return;
  widgetId=ts.render(form.querySelector('#captcha'),{sitekey:SITE_KEY,action:'booking',language:lang,theme:skin==='glass'?'auto':'dark',callback:t=>{token=t;button.disabled=busy},'expired-callback':()=>{token='';button.disabled=true},'error-callback':()=>{token='';button.disabled=true;if(form.isConnected)msg(tr('Sicherheitsprüfung fehlgeschlagen. Bitte neu laden.','Security check failed. Please reload.','Перевірка не вдалася. Оновіть сторінку.'));}});
 }catch{if(form.isConnected)msg(tr('Sicherheitsprüfung nicht verfügbar. Bitte neu laden.','Security check unavailable. Please reload.','Перевірка недоступна. Оновіть сторінку.'));return;}
 form.onsubmit=async e=>{e.preventDefault();if(busy||!token)return;if(!$('date').value||!$('time').value){msg(tr('Bitte wählen Sie einen freien Termin.','Choose an available time slot.','Оберіть доступний час.'));return;}const now=viennaNow();if($('date').value===now.date && $('time').value<=now.time){msg(tr('Bitte wählen Sie eine zukünftige Uhrzeit.','Please choose a future time.','Оберіть час у майбутньому.'));return;}if(!form.reportValidity())return;busy=true;button.disabled=true;const id=widgetId;
 const payload={p_name:$('name').value,p_email:$('email').value,p_service:$('service').value,p_mode:$('mode').value,p_date:$('date').value,p_time:$('time').value,p_details:$('details').value,p_language:lang,token};
 try{const response=await fetch(cfg.url.replace(/\/$/,'')+'/functions/v1/book-appointment',{method:'POST',headers:{'Content-Type':'application/json','apikey':cfg.key},body:JSON.stringify(payload)});
 const data=await response.json();if(!response.ok||data.ok!==true)throw new Error(data.error||'request_failed');
 if(form.isConnected){form.reset();form.tfCalendarRefresh?.();msg(tr('Anfrage gesendet. Noch nicht bestätigt.','Request sent. Not yet confirmed.','Запит надіслано. Ще не підтверджено.'),true)}
 }catch(e){if(form.isConnected){const errors={slot_unavailable:tr('Termin nicht mehr verfügbar. Bitte neu wählen.','Slot no longer available. Choose another time.','Час уже недоступний. Оберіть інший.'),rate_limit:tr('Zu viele Anfragen. Bitte später erneut versuchen.','Too many requests. Please try again later.','Забагато запитів. Спробуйте пізніше.'),captcha_failed:tr('Sicherheitsprüfung abgelaufen. Bitte erneut bestätigen.','Security check expired or failed. Please verify again.','Перевірка не пройшла або застаріла. Повторіть її.'),invalid_input:tr('Bitte prüfen Sie Datum, Uhrzeit und Eingaben.','Check the date, time and form details.','Перевірте дату, час і дані форми.'),origin_not_allowed:tr('Buchung nur auf der freigegebenen Website möglich.','Booking is only available on the approved website.','Запис доступний лише на дозволеному сайті.'),too_large:tr('Die Anfrage ist zu lang.','The request is too long.','Запит занадто довгий.'),unavailable:tr('Dienst vorübergehend nicht verfügbar.','Service temporarily unavailable.','Сервіс тимчасово недоступний.')};if(e.message==='slot_unavailable')form.tfCalendarRefresh?.();msg(errors[e.message]||tr('Anfrage fehlgeschlagen. Bitte erneut versuchen.','Request failed. Please try again.','Помилка. Спробуйте ще раз.'));}}
 finally{busy=false;token='';button.disabled=true;if(form.isConnected&&widgetId===id)try{window.turnstile.reset(id)}catch{}}
 };
}
