const aboutPage=()=>`<div class="profile-layout"><section class="card profile-main"><p class="eyebrow">${tr('DER MENSCH HINTER TECHFIX','THE PERSON BEHIND TECHFIX','ЛЮДИНА ЗА TECHFIX')}</p><h1>${tr('Hallo, ich bin Daniel.','Hi, I’m Daniel.','Привіт, я Даніел.')}</h1><p>${tr('Ich bin 21 Jahre alt, komme ursprünglich aus Roswell, Georgia, USA, und lebe heute in St. Pölten. An der USTP studiere ich Schienenfahrzeugtechnologie.','I’m 21, originally from Roswell, Georgia, USA, and now based in St. Pölten, Austria. I study Rail Vehicle Technology at USTP.','Мені 21 рік. Я родом із Розвелла, штат Джорджія, США, а зараз живу в Санкт-Пельтені, Австрія. В USTP вивчаю технології рейкових транспортних засобів.')}</p><p>${tr('Computer faszinieren mich seit meiner Kindheit. Ich habe fünf Jahre praktische IT-Erfahrung, einen Studienabschluss in Cybersicherheit am Igor Sikorsky Kyiv Polytechnic Institute und drei Jahre Erfahrung als IT-Lehrkraft.','Computers have fascinated me from an early age. I have five years of practical IT experience, a degree in cybersecurity from Igor Sikorsky Kyiv Polytechnic Institute and three years of experience teaching IT.','Комп’ютери захоплюють мене з дитинства. Маю п’ять років практичного досвіду в ІТ, диплом із кібербезпеки КПІ ім. Ігоря Сікорського та три роки досвіду викладання ІТ.')}</p><p>${tr('TechFix entstand aus meiner Begeisterung für Technik. Ich verbinde technisches Wissen mit persönlicher, verständlicher Unterstützung. In meiner Freizeit interessieren mich Fahrzeuge, Technik, Natur und Reisen.','TechFix grew out of my love for technology. I combine technical knowledge with personal, approachable support. Outside IT, I enjoy vehicles, technology, nature and travel.','TechFix виник із моєї любові до технологій. Я поєдную технічні знання з особистою та зрозумілою підтримкою. У вільний час захоплююся транспортом, технікою, природою та подорожами.')}</p></section><aside class="card profile-mark"><img class="profile-portrait" src="${PORTRAIT}" alt="${tr('Porträt von Daniel','Portrait of Daniel','Портрет Даніела')}" width="240" height="320"><h2>Daniel</h2><p>${tr('IT-Service · Cybersicherheit · Technik','IT support · Cybersecurity · Engineering','ІТ-підтримка · Кібербезпека · Техніка')}</p><div class="chips"><span class="chip-label">St. Pölten, AT</span></div></aside></div>${profileStats()}<div class="profile-layout"><article class="card"><h2>${tr('Erfahrung & Ausbildung','Experience & education','Досвід та освіта')}</h2><div class="timeline">${[[tr('USTP · Schienenfahrzeugtechnologie','USTP · Rail Vehicle Technology','USTP · Технології рейкових транспортних засобів'),tr('Derzeitiges Studium in St. Pölten.','Current studies in St. Pölten.','Нинішнє навчання в Санкт-Пельтені.')],[tr('Studienabschluss in Cybersicherheit','Degree in cybersecurity','Диплом у сфері кібербезпеки'),tr('Igor Sikorsky Kyiv Polytechnic Institute · Schwerpunkt Cybersicherheit.','Igor Sikorsky Kyiv Polytechnic Institute · Cybersecurity.','КПІ ім. Ігоря Сікорського · Кібербезпека.')],[tr('IT-Lehrkraft · 3 Jahre','IT teacher · 3 years','Викладач ІТ · 3 роки'),tr('Unterricht in IT, unter anderem Design und Programmierung.','Taught IT, including design and programming.','Викладання ІТ, зокрема дизайну та програмування.')],['NBU',tr('Mitarbeiter im Bereich Cybersicherheit mit Aufgaben in der Softwareentwicklung.','Cybersecurity officer with software development responsibilities.','Фахівець із кібербезпеки, також займався розробкою програмного забезпечення.')],['GICHD · 2023',tr('Praktikum im Informationsmanagement.','Information management internship.','Стажування з інформаційного менеджменту.')]].map(([h,p])=>`<div class="timeline-item"><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></article><article class="card"><h2>${tr('Sprachen','Languages','Мови')}</h2>${[[tr('Englisch','English','Англійська'),'C1'],[tr('Deutsch','German','Німецька'),'B1'],[tr('Ukrainisch','Ukrainian','Українська'),'C2'],[tr('Russisch','Russian','Російська'),'C2']].map(([l,v])=>`<div class="language-row"><span>${l}</span><span class="language-level">${v}</span></div>`).join('')}<h2 class="section-heading">${tr('Interessen','Interests','Інтереси')}</h2><div class="chips">${[tr('Fahrzeuge','Vehicles','Транспорт'),tr('Technik','Technology','Техніка'),tr('Natur','Nature','Природа'),tr('Reisen','Travel','Подорожі')].map(x=>`<span class="chip-label">${x}</span>`).join('')}</div></article></div><article class="card research-card"><p class="eyebrow">${tr('WISSENSCHAFT & FORSCHUNG','ACADEMIC RESEARCH','НАУКОВІ ДОСЛІДЖЕННЯ')}</p><h2>${tr('Risikobewertung der lateralen Bewegung von APT-Akteuren in ein SCADA-Segment in einer Active-Directory-Umgebung','Risk Assessment of APT Lateral Movement into a SCADA Segment in an Active Directory Environment','Оцінювання ризику латерального руху APT до SCADA-сегмента в середовищі Active Directory')}</h2><p class="small">${tr('Konferenzbeitrag · KPI · 2026 · D. Danylenko, L. Yu. Halchynskyi','Conference contribution · KPI · 2026 · D. Danylenko, L. Yu. Halchynskyi','Матеріали конференції · КПІ · 2026 · Д. Даниленко, Л. Ю. Гальчинський')}</p><p>${tr('Die Arbeit untersucht Konfigurationsrisiken in Active Directory anhand eines Graphmodells. Der entwickelte Prototyp ADAPT Analyzer unterstützt die Bewertung möglicher Angriffspfade zu kritischen Ressourcen.','The research uses a graph model to assess Active Directory configuration risks. The ADAPT Analyzer prototype helps evaluate potential attack paths to critical resources.','У роботі використано графову модель для оцінювання конфігураційних ризиків Active Directory. Прототип ADAPT Analyzer допомагає оцінювати потенційні шляхи атак до критичних ресурсів.')}</p><div class="chips"><span class="chip-label">Active Directory</span> <span class="chip-label">SCADA</span> <span class="chip-label">ADAPT Analyzer</span> <span class="chip-label">${tr('Risikobewertung','Risk assessment','Оцінювання ризиків')}</span></div><a class="button secondary" href="https://conf.ipt.kpi.ua/arxiv/2026-xxiv/" target="_blank" rel="noopener noreferrer">${tr('Konferenzbeitrag ansehen','View conference entry','Переглянути матеріали конференції')} ↗</a></article>${skillsBlock()}${practical()}`;
