let skin='green';try{skin=localStorage.getItem('techfix-skin-v5')||'green'}catch{};if(!['green','amber','glass'].includes(skin))skin='green';
function applySkin(){document.documentElement.dataset.skin=skin;$('skin').value=skin;$('theme').hidden=skin!=='glass';document.querySelector('meta[name="theme-color"]').content=skin==='glass'?'#f5f7fa':'#07100b';}
applySkin();$('skin').onchange=e=>{skin=e.target.value;try{localStorage.setItem('techfix-skin-v5',skin)}catch{}applySkin();};
$('skip').onclick=e=>{e.preventDefault();$('main').focus();};
const consoleCommands=['help','whoami','services','skills','research','portfolio','booking','contact','theme','clear'];
const consoleDescriptions=()=>[tr('Befehle anzeigen','List commands','Список команд'),tr('Über Daniel','About Daniel','Про Даніела'),tr('Preise und Leistungen','Services and prices','Послуги та ціни'),tr('Technische Kompetenzen','Technical skills','Технічні навички'),tr('Forschung öffnen','Open research','Відкрити дослідження'),tr('Projekte ansehen','View projects','Переглянути проєкти'),tr('Termin anfragen','Request appointment','Записатися'),tr('Kontakt öffnen','Open contact','Відкрити контакти'),tr('green / amber / glass','green / amber / glass','green / amber / glass'),tr('Ausgabe löschen','Clear output','Очистити вивід')];
const consolePanel=()=>`<section class="terminal-panel" aria-label="${tr('Interaktives Terminal','Interactive terminal','Інтерактивний термінал')}"><div class="terminal-bar"><span class="terminal-lights" aria-hidden="true"><i></i><i></i><i></i></span><span>guest@techfix:~</span><span>v5.1</span></div><div class="terminal-inner"><div class="terminal-intro"><span class="terminal-kicker">// INTERACTIVE SHELL</span><h2>${tr('Probieren Sie es aus.','Try a command.','Спробуйте команду.')}</h2><p>${tr('Tippen Sie help oder wählen Sie einen Befehl.','Type help or choose a command.','Введіть help або оберіть команду.')}</p></div><div class="command-chips">${['help','whoami','services','booking','contact'].map(c=>`<button type="button" data-command="${c}">${c}</button>`).join('')}</div><div id="terminal-output" class="terminal-output" role="log" aria-live="polite"><div class="boot-line">[ OK ] ${tr('Oberfläche geladen','Interface loaded','Інтерфейс завантажено')}</div><div class="boot-line">[ OK ] ${tr('Befehle verfügbar','Commands ready','Команди готові')}</div><div class="terminal-hint">${tr('Lokales Demo-Terminal · kein Systemzugriff','Local interactive shell · no system access','Локальний термінал · без доступу до системи')}</div></div><form id="terminal-form" class="terminal-form"><label for="terminal-command" class="prompt">guest@techfix:~$</label><input id="terminal-command" placeholder="help" aria-label="${tr('Befehl','Command','Команда')}" autocomplete="off" spellcheck="false" maxlength="80"><button type="submit" aria-label="${tr('Ausführen','Run command','Виконати')}">↵</button></form></div></section>`;
function bindTerminal(){const f=$('terminal-form');if(!f)return;const input=$('terminal-command'),output=$('terminal-output');let history=[],cursor=0;
 function append(str,cls){const el=document.createElement('div');el.className=cls||'';el.textContent=str;output.append(el);while(output.children.length>45)output.firstChild.remove();output.scrollTop=output.scrollHeight;}
 function run(raw){const cmd=raw.trim().toLowerCase();if(!cmd)return;history.push(raw);cursor=history.length;input.value='';if(cmd==='clear'){output.replaceChildren();return;}append('guest@techfix:~$ '+raw,'command-echo');const routes={whoami:'about',portfolio:'portfolio',research:'portfolio',booking:'booking',contact:'contact',services:'services'};
 if(cmd==='help'){append(consoleCommands.map((c,i)=>c.padEnd(12)+consoleDescriptions()[i]).join('\n'));return;}
 if(cmd==='skills'){append(skillGroups().map(([h,a])=>h+': '+a.join(' · ')).join('\n'));return;}
 if(cmd==='theme'){append('theme green | theme amber | theme glass');return;}
 if(/^theme (green|amber|glass)$/.test(cmd)){skin=cmd.split(' ')[1];$('skin').value=skin;$('skin').onchange({target:$('skin')});append('[ OK ] '+skin);return;}
 if(cmd==='whoami'){append('Daniel · St. Pölten, AT\n'+tr('5 Jahre IT · 3 Jahre Unterricht','5 years IT · 3 years teaching','5 років ІТ · 3 роки викладання')+'\nEN C1 · DE B1 · UA C2 · RU C2');}
 if(cmd==='services'){append(services().map(s=>s[1]+' — €'+s[2]+(s[0]==='remote'?'/h':'')).join('\n'));}
 if(cmd==='contact'){append('dtranslateat@gmail.com\nTelegram / Instagram: @techfixat');}
 if(routes[cmd]){const a=document.createElement('a');a.href='#'+routes[cmd];a.textContent=tr('Seite öffnen →','Open page →','Відкрити сторінку →');a.className='terminal-route';output.append(a);output.scrollTop=output.scrollHeight;if(['booking','portfolio','research','contact'].includes(cmd))location.hash=routes[cmd];return;}
 append(tr('Unbekannter Befehl. Tippen Sie help.','Command not found. Type help.','Невідома команда. Введіть help.'));}
 f.onsubmit=e=>{e.preventDefault();run(input.value)};f.parentElement.querySelectorAll('[data-command]').forEach(b=>b.onclick=()=>{run(b.dataset.command);if(input.isConnected)input.focus()});input.onkeydown=e=>{if(e.key==='ArrowUp'&&history.length){e.preventDefault();cursor=Math.max(0,cursor-1);input.value=history[cursor]}if(e.key==='ArrowDown'&&history.length){e.preventDefault();cursor=Math.min(history.length,cursor+1);input.value=history[cursor]||''}};
}
