if(p==='privacy')m.innerHTML=`<h1>${labels()[pages.indexOf(p)]}</h1><div class="card"><p>${tr('Kontakt: dtranslateat@gmail.com. Vollständige rechtliche Angaben und Datenschutzhinweise müssen vor dem kommerziellen Start ergänzt werden.','Contact: dtranslateat@gmail.com. Full legal details and privacy information must be completed before commercial launch.','Контакт: dtranslateat@gmail.com. Повні юридичні дані та інформацію про конфіденційність потрібно додати до комерційного запуску.')}</p>${p==='privacy'?`<p>${tr('Terminanfragen enthalten Kontaktdaten und Problembeschreibungen. Sie dienen der Bearbeitung Ihrer Anfrage. Keine Passwörter eingeben.','Booking requests contain contact details and problem descriptions used to handle your request. Do not enter passwords.','Запити містять контактні дані та опис проблеми для обробки запису. Не вводьте паролі.')}</p>`:''}<a href="#booking">${labels()[4]}</a></div>`;
