const statusText=s=>({all:tr('Alle','All','Усі'),pending:tr('Offen','Pending','Очікує'),confirmed:tr('Bestätigt','Confirmed','Підтверджено'),declined:tr('Abgelehnt','Declined','Відхилено'),completed:tr('Erledigt','Completed','Завершено'),cancelled:tr('Storniert','Cancelled','Скасовано')})[s]||s;
