async function admin(){
 const m=$('main'), version=viewVersion, active=()=>page()==='admin'&&version===viewVersion;
 m.innerHTML=`<p class="eyebrow">TECHFIX / WORKSPACE</p><h1>${tr('Verwaltung','Admin dashboard','Адмінпанель')}</h1><p id="message" role="status" aria-live="polite"></p>`;
 if(!configured||location.protocol==='file:'){msg(tr('Vorschau: Supabase konfigurieren und die Website über HTTPS öffnen.','Preview: configure Supabase and open the deployed website over HTTPS.','Попередній перегляд: налаштуйте Supabase та відкрийте сайт через HTTPS.'));return;}
 const db=await getDb(); const {data:{session},error:sessionError}=await db.auth.getSession(); if(!active())return;
 if(sessionError){msg(tr('Sitzung konnte nicht geladen werden.','Could not load session.','Не вдалося завантажити сеанс.'));return;}
 if(!session){m.insertAdjacentHTML('beforeend',`<form id="login">${field('email','Email','email','autocomplete="username"')}${field('password',tr('Passwort','Password','Пароль'),'password','autocomplete="current-password"')}<button>${tr('Anmelden','Sign in','Увійти')}</button></form>`);const form=$('login');form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const {error}=await db.auth.signInWithPassword({email:$('email').value,password:$('password').value});if(!active())return;if(error)msg(tr('Anmeldung fehlgeschlagen. Bitte Zugangsdaten prüfen.','Sign-in failed. Check your credentials.','Не вдалося увійти. Перевірте дані.'));else render();}catch{if(active())msg(tr('Verbindungsfehler.','Connection error.','Помилка з’єднання.'));}finally{b.disabled=false;}};return;}
 const out=document.createElement('button');out.textContent=tr('Abmelden','Sign out','Вийти');out.onclick=async()=>{out.disabled=true;try{const {error}=await db.auth.signOut();if(active()){if(error){msg(tr('Abmelden fehlgeschlagen.','Sign-out failed.','Не вдалося вийти.'));out.disabled=false;}else render();}}catch{if(active()){msg(tr('Verbindungsfehler.','Connection error.','Помилка з’єднання.'));out.disabled=false;}}};m.append(out);
 // Existing allowlist function is executable by authenticated users. RLS remains the actual authorization boundary.
 const check=await db.rpc('is_admin');if(!active())return;if(check.error||check.data!==true){msg(tr('Kein Administratorzugriff oder Verbindung fehlgeschlagen.','Administrator access denied or connection failed.','Немає доступу адміністратора або помилка з’єднання.'));return;}
 const {data,error,truncated}=await tfLoadBookings(db);if(!active())return;if(error||!Array.isArray(data)){msg(tr('Termine konnten nicht geladen werden.','Could not load appointments.','Не вдалося завантажити записи.'));return;}
 if(truncated)m.append(tfElement('p',tr('Nur die neuesten 10000 Datensätze.','Only the latest 10,000 bookings are shown.','Показано лише останні 10000 записів.'),'small'));const stats=document.createElement('div');stats.className='stats';m.append(stats);
 const toolbar=document.createElement('div');toolbar.className='admin-toolbar';m.append(toolbar);
 const search=document.createElement('input');search.type='search';search.placeholder=tr('Suchen…','Search…','Пошук…');search.setAttribute('aria-label',search.placeholder);toolbar.append(search);
 const filter=document.createElement('select');filter.setAttribute('aria-label',tr('Status filtern','Filter status','Фільтр статусу'));['all','pending','confirmed','declined','completed','cancelled'].forEach(x=>filter.add(new Option(statusText(x),x)));toolbar.append(filter);
 const refresh=document.createElement('button');refresh.textContent=tr('Aktualisieren','Refresh','Оновити');refresh.onclick=()=>render();toolbar.append(refresh);
 const wrap=document.createElement('div');wrap.className='table';m.append(wrap);let sortKey=2,sortDir=1;let saving=false;
 const fields=r=>[r.name+' / '+r.email,serviceText(r.service)+' / '+modeText(r.mode),r.request_date+' '+r.request_time,r.details,statusText(r.status)];
 function draw(){stats.replaceChildren();for(const [label,value] of [[tr('Anfragen','Requests','Запити'),data.length],[tr('Offen','Pending','Очікують'),data.filter(x=>x.status==='pending').length],[tr('Bestätigt','Confirmed','Підтверджено'),data.filter(x=>x.status==='confirmed').length],[tr('Erledigt','Completed','Завершено'),data.filter(x=>x.status==='completed').length]]){const div=document.createElement('div');div.className='stat';const num=document.createElement('strong');num.textContent=value;const title=document.createElement('span');title.textContent=label;div.append(num,title);stats.append(div)}
 wrap.replaceChildren();const t=document.createElement('table'),head=t.createTHead().insertRow(),body=t.createTBody();
 [tr('Kunde','Customer','Клієнт'),tr('Leistung','Service','Послуга'),tr('Termin (Wien)','Requested (Vienna)','Дата (Відень)'),tr('Problem','Problem','Проблема'),tr('Status','Status','Статус'),tr('Aktion','Action','Дія')].forEach((x,i)=>{const th=document.createElement('th');if(i<5){const b=document.createElement('button');b.textContent=x+(sortKey===i?(sortDir===1?' ↑':' ↓'):'');th.setAttribute('aria-sort',sortKey===i?(sortDir===1?'ascending':'descending'):'none');b.onclick=()=>{if(saving)return;sortDir=sortKey===i?-sortDir:1;sortKey=i;draw()};th.append(b)}else th.textContent=x;head.append(th)});
 const shown=data.filter(r=>(filter.value==='all'||r.status===filter.value)&&fields(r).join(' ').toLowerCase().includes(search.value.trim().toLowerCase())).sort((a,b)=>String(fields(a)[sortKey]).localeCompare(String(fields(b)[sortKey]),lang)*sortDir);
 if(!shown.length){const empty=body.insertRow().insertCell();empty.colSpan=6;empty.className='empty';empty.textContent=tr('Keine Anfragen gefunden.','No appointments found.','Записів не знайдено.')}
 for(const r of shown){const row=body.insertRow();fields(r).slice(0,4).forEach(x=>row.insertCell().textContent=x);const s=document.createElement('select');s.setAttribute('aria-label',tr('Status für','Status for','Статус для')+' '+r.name);['pending','confirmed','declined','completed','cancelled'].forEach(x=>s.add(new Option(statusText(x),x)));s.value=r.status;row.insertCell().append(s);const b=document.createElement('button');b.textContent=tr('Speichern','Save','Зберегти');b.onclick=async()=>{if(saving||s.value===r.status)return;saving=true;b.disabled=true;s.disabled=true;const newStatus=s.value;try{const {data:updated,error}=await db.from('bookings').update({status:newStatus}).eq('id',r.id).select('id');if(!active())return;if(error||updated?.length!==1)msg((error?.code==='23505'||error?.message==='Slot unavailable')?tr('Dieser Termin ist nicht verfügbar.','This slot is unavailable.','Цей час недоступний.'):tr('Änderung fehlgeschlagen.','Update failed.','Не вдалося зберегти.'));else{r.status=newStatus;msg(tr('Gespeichert.','Saved.','Збережено.'),true);draw();}}catch{if(active())msg(tr('Verbindungsfehler.','Connection error.','Помилка з’єднання.'));}finally{saving=false;b.disabled=false;s.disabled=false;}};row.insertCell().append(b)}wrap.append(t)}
 filter.onchange=()=>{if(!saving)draw()};search.oninput=()=>{if(!saving)draw()};draw();tfMission(db,m,data,active);
}
$('lang').onchange=e=>{lang=e.target.value;try{localStorage.setItem('techfix-lang',lang);}catch{}render()};let tfMotionAnimation=null,tfMotionTimer=0;
function tfAnimateRoute(){
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const main=$('main'),meter=document.getElementById('tf-route-meter');
 if(tfMotionAnimation)tfMotionAnimation.cancel();
 if(main.animate)tfMotionAnimation=main.animate([{opacity:.58,transform:'translateY(9px)'},{opacity:1,transform:'translateY(0)'}],{duration:270,easing:'cubic-bezier(.2,.8,.2,1)'});
 if(meter){clearTimeout(tfMotionTimer);meter.hidden=true;void meter.offsetWidth;meter.hidden=false;tfMotionTimer=setTimeout(()=>{meter.hidden=true},430);}
}
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'});tfAnimateRoute()});render();
